class Container(containers.DeclarativeContainer):
    config = providers.Configuration()
    repo = providers.Factory(SqlOrderRepository, dsn=config.dsn)
    service = providers.Factory(OrderService, repo=repo, clock=SystemClock())

@inject
def handler(svc: OrderService = Provide[Container.service]):
    return svc.get()

def get_repo() -> OrderRepository:
    return SqlOrderRepository(app_state.pool)

def get_service(repo: OrderRepository = Depends(get_repo)) -> OrderService:
    return OrderService(repo, SystemClock())

@app.get("/orders/{id}")
async def read(id: int, svc: OrderService = Depends(get_service)):
    return svc.get(id)
